insert into public.promotions (id, image_path, is_active, slug, title_i18n, body_i18n, cta_label_i18n, cta_href, starts_on, ends_on, sort_order) values
  ('19e49c6f-a685-8a43-9ce5-cbe3992ba8ef', null, true, 'kottu-tuesdays', '{"en":"Kottu Tuesdays","si":"කොත්තු අඟහරුවාදා","ta":"கொத்து செவ்வாய்"}'::jsonb, '{"en":"Every Tuesday from 6pm: any kottu and a king coconut for Rs. 1,800."}'::jsonb, '{"en":"Order kottu","si":"කොත්තු ඇණවුම් කරන්න","ta":"கொத்து ஆர்டர் செய்யுங்கள்"}'::jsonb, '/menu#kottu', null, null, 1),
  ('2e767d25-c67e-8b26-ba2c-ddb20e6fe20e', null, true, 'sunday-family-feast', '{"en":"Sunday rice & curry for four","si":"ඉරිදා පවුලේ බත් පැකේජය","ta":"ஞாயிறு குடும்ப விருந்து"}'::jsonb, '{"en":"Four rice & curry plates, a hopper basket and wattalappan for Rs. 6,950. Sundays only."}'::jsonb, '{"en":"See rice & curry","si":"බත් සහ කරි බලන්න","ta":"சோறும் கறியும் பார்க்க"}'::jsonb, '/menu#rice-and-curry', null, null, 2),
  ('e2843231-c66d-86fe-ba36-ba868da29c39', null, true, 'poya-vegetarian-lunch', '{"en":"Poya day vegetarian lunch","si":"පොහොය දින නිර්මාංශ දිවා ආහාරය","ta":"போயா தின சைவ மதிய உணவு"}'::jsonb, '{"en":"On every Poya day: seven vegetable curries, rice and a dessert for Rs. 1,450. Our bar stays closed."}'::jsonb, '{"en":"View the menu","si":"මෙනුව බලන්න","ta":"மெனுவைப் பார்க்க"}'::jsonb, '/menu#rice-and-curry', null, null, 3),
  ('c52a2d51-e839-8095-bd22-6617509b852d', null, true, 'christmas-love-cake', '{"en":"Christmas love cake","si":"නත්තල් ලව් කේක්","ta":"கிறிஸ்துமஸ் லவ் கேக்"}'::jsonb, '{"en":"Pre-order a whole love cake or breudher for the festive table."}'::jsonb, '{"en":"Ask us","si":"අපෙන් අහන්න","ta":"எங்களிடம் கேளுங்கள்"}'::jsonb, '/contact', '2026-12-01', '2026-12-26', 4)
