insert into public.reviews (id, branch_id, author_name, rating, body, status, created_at) values
  ('79530695-c968-892b-873f-b1c5a6961971', 'fae51e30-e4ad-8bc6-83b8-a6d4705e3ee0', 'Nadeesha P.', 5, 'The dolphin kottu is ridiculous in the best way. Ordered for the office and it arrived hot, with extra gravy in a separate tub. Thoughtful.', 'approved', '2026-09-12T13:20:00+05:30'),
  ('4fb86353-65f9-8b30-bcda-3e65f9efd99e', 'ffc2297a-852a-8f50-b9b2-e426e7dfb4cd', 'Arjun K.', 5, 'Egg hoppers that taste like my aachchi''s. Crisp edges, runny yolk, proper lunu miris. We come every Friday now.', 'approved', '2026-09-03T20:05:00+05:30'),
  ('3b301fff-a460-85ac-86a9-cc8b5edff623', 'fae51e30-e4ad-8bc6-83b8-a6d4705e3ee0', 'Fathima R.', 4, 'Lovely to find a place that marks halal clearly. The chicken biriyani was fragrant and generous. Service was a little slow on a busy night.', 'approved', '2026-08-28T19:40:00+05:30'),
  ('cab37864-9811-80c9-ba30-913459b90d98', 'bf4db4fb-e61a-8ce2-8138-eb5aeda9ecd1', 'Dilshan W.', 5, 'Booked a table for twelve after a perahera and they handled it beautifully. The wattalappan alone is worth the trip.', 'approved', '2026-08-17T21:15:00+05:30'),
  ('36d24bcf-6add-8e06-8ab9-0048ab5a2f92', 'ffc2297a-852a-8f50-b9b2-e426e7dfb4cd', 'Priya S.', 5, 'Catered my mother''s almsgiving for forty. Everything was on time, labelled, and the vegetable curries were outstanding.', 'approved', '2026-07-30T11:00:00+05:30'),
  ('c1459157-1e7f-8ba8-bcf5-39244cfd8bdf', 'bf4db4fb-e61a-8ce2-8138-eb5aeda9ecd1', 'Tom H.', 4, 'First proper Sri Lankan meal of our trip. Staff explained every dish and the ''Medium'' spice was still an adventure for us.', 'approved', '2026-07-21T14:30:00+05:30')
